\section{Introduction}

Few-level atomic and molecular systems play crucial roles in quantum control and quantum information processing.
For example, qubits have great advantages in certain computational tasks compared to classical bits because of quantum coherence
and quantum entanglement. However,
for an open quantum system, mutual effects due to the coupling between the system and environment are inevitable and result in very complex
reduced dynamics including dissipation, fluctuation, decoherence and disentanglement \cite{decoherence1,decoherence1a,Entanglement1,YuEberly1,decoherence1b,decoherence2}.

\begin{align} \label{effective H depashing under control}
\widetilde{H} &= \exp\left[-i\int_{0}^{t}H_{\rm ctr}(s)ds\right] H_{\rm tot} \exp\left[i\int_{0}^{t}H_{\rm ctr}(s)ds\right] \non\\
&= \widetilde{H}_{\rm sys}+H_{\rm env}+\widetilde{H}_{\rm int},
\end{align}
where the effective system Hamiltonian and system-environment interaction Hamiltonian are given by:
\beqa \label{flip over}
\widetilde{H}_{\rm sys}&=&\om p(t)J_{z}, \non\\
\widetilde{H}_{\rm int}&=&\sum_{n}p(t)J_{z}(g_{n}b_{n}^{\dagger}+g_{n}^*b_{n}).
\eeqa

The exact dynamics for the three-level atomic system under both the environmental noise and control pulses can be compactly described
by the non-Markovian QSD equation derived from the above total Hamiltonian in the toggling frame:
\begin{equation} \label{QSD}
\frac{\partial}{\partial t}\psi_{t}=-i\widetilde{H}_{\rm sys}\psi_{t}+Lz_{t}^{\ast}\psi
_{t}-L^{\dagger}
{\displaystyle\int\nolimits_{0}^{t}}
ds\alpha(t-s)\frac{\delta\psi_{t}}{\delta z_{s}^{\ast}},
\end{equation}
where $L=p(t)J_{z}$ is the modified system Lindblad operator incorporating both the effects of environment and the external control pulses.
Note that the correlation function  $\alpha(t-s)=\sum_n |g_n|^2e^{-i\om_n(t-s)}$ is arbitrary and $z_t^*=-i\sum_n g_nz_n^*e^{iw_n t}$
is a complex Gaussian process satisfying $M[z_t]=M[z_tz_s]=0$ and $M[z_tz_s^*]=\al(t,s)$. Here $M[\, .\, ]$ denotes the statistical average
 over the classical Gaussuan noise $z_t$. When $\al(t,s)=\Gamma \delta(t-s)$, the noise $z^*_t$ reduces to the memoryless white noise.

\begin{equation}
\label{Ffunction}
\frac{d}{dt}F(t)=\frac{\gamma}{2}p(t)-\gamma F(t).
\end{equation}
With (\ref{Ffunction}),  the QSD Eq.~(\ref{QSD for controlled depha}) is fully determined. We first compute the fidelity and the angular momentum time evolution
with different numbers of control pulses. The plots are shown in Fig.~1.

\begin{figure}[htb]
\centering\includegraphics[width = 7cm]{1.eps}
\caption{Ensemble average of Fidelity and $\la \vec{J}\ra$ over 2000 trajectories of the single qutrit dephasing model under different UDD control sequences. We choose the initial state $|\psi_0\ra=\frac{1}{\sqrt{3}}(|0\ra+|1\ra+|2\ra)$ and the environment memory parameter $\ga=1$. The black solid line represents the Fidelity, red dotted line denotes $\la J_x \ra$, green dashed line denotes $\la J_y \ra$ and blue dot-dashed line denotes $\la J_z\ra$. }
\label{dephasing_0,20,40pulses}
\end{figure}

\begin{figure}[htb]
\centering\includegraphics[width = 8cm]{2.eps}
\caption{Fidelity evolution of the single qutrit dephasing model under 20 control pulses UDD sequence with different environment memory parameter $\ga$. The initial state $|\psi_0\ra=\frac{1}{\sqrt{3}}(|0\ra+|1\ra+|2\ra)$.}
\label{dephasing_different_gamma}
\end{figure}

\begin{figure}[htb]
\centering\includegraphics[width = 8cm]{3.eps}
\caption{ Fidelity time evolution of a single-qutrit dephasing model with the initial state $\rho_0=\frac{1-M}{2}I_3+\frac{3M-1}{2}|\psi_0\ra\la\psi_0|$, where $M$ is the degree of mixing and $|\psi(0)\ra=\frac{1}{\sqrt{3}}(|0\ra+|1\ra+|2\ra)$. The environment memory time $t=1/\gamma$ with $\ga=1$.}
\label{dephasing_mixed}
\end{figure}

Another interesting situation is that the initial state of the three-level system is a mixed state. Since any initial mixed state can be represented as $\rho_0=\sum_\lambda c_\lambda |\psi_{\lambda,0}\ra\la\psi_{\lambda,0}|$, then the density matrix at time $t$ is simply  expressed in terms of QSD solutions: $\rho_t=\sum_\lambda c_\lambda M[ |\psi_{\lambda,t}\ra\la\psi_{\lambda,t}|]$, where $|\psi_{\lambda,t}\ra$ is governed by the QSD Eq. (\ref{QSD for controlled depha}).

\begin{figure}[htb]
\centering\includegraphics[width = 8cm]{4.eps}
\caption{ Ensemble average of Fidelity and $\la \vec{J}\ra$ over 2000 trajectories of the single qutrit dissipative model under different UDD control sequences. We choose the initial state $|\psi_0\ra=\frac{1}{\sqrt{3}}(|0\ra+|1\ra+|2\ra)$ and the environment memory parameter $\ga=1$. The black solid line represents the Fidelity, red dotted line denotes $\la J_x \ra$, green dashed line denotes $\la J_y \ra$ and blue dot-dashed line denotes $\la J_z\ra$. }
\label{dissi_different_pulses}
\end{figure}

\begin{figure}[htb]
\centering\includegraphics[width = 6.5cm]{5.eps}
\caption{Fidelity evolution of single qutrit dissipative model under control with different environment memory parameter $\ga$. We apply two-layer nesting UDD control sequences with the outer layer $N_1=20$ and the inner layer $N_2=10$. The initial state $|\psi(0)\ra=\frac{1}{\sqrt{3}}(|0\ra+|1\ra+|2\ra)$.}
\label{dissi_different_gamma}
\end{figure}

The numerical results with 2000 realizations are plotted in Fig.~\ref{dissi_different_pulses}. For the zero-temperature environment, without any control pulses, the spontaneous emission always causes the three-level system to decay into the ground state. So in Fig.~\ref{dissi_different_pulses} (a), when $t \rightarrow \infty$, we get $\la J_x \ra,\la J_y \ra \rightarrow 0 $ and $\la J_z \ra \rightarrow -1$. Beyond single UDD control sequence for dephasing model, by applying two layers of nesting UDD control sequences, we can also successfully resist the dissipation (Fig.~\ref{dissi_different_pulses} (a), (b) and (c)).

\begin{figure}[htb]
\centering\includegraphics[width = 8.3cm]{6.eps}
\caption{ Fidelity time evolution of a single-qutrit dissipative model with the initial state $\rho_0=\frac{1-M}{2}I_3+\frac{3M-1}{2}|\psi_0\ra\la\psi_0|$, where $M$ is the degree of mixing and $|\psi(0)\ra=\frac{1}{\sqrt{3}}(|0\ra+|1\ra+|2\ra)$. The environment memory index $\ga=1$.}
\label{dissi_mixed}
\end{figure}

